function UIGamePlayGuideDialog:InitListener()

    KTool.GetOrAddComponent(self.Btn_Exit.gameObject, typeof(UIEventProxy)).onPointerClick = function()
        if GamePlayGuideMgr then
            GamePlayGuideMgr:Delete()
            GamePlayGuideMgr = nil
        end
        UIModule.CloseDialog(self.controller)
    end

    KTool.GetOrAddComponent(self.Btn_ToNext.gameObject, typeof(UIEventProxy)).onPointerClick = function()
        if IsNull(GamePlayGuideMgr) then return end
        if not IsNull(self.coShowImgHighLight) and not IsNull(self.Layer_Mask.CoShowFocus) then
            --- 高亮框 终点
            --- 赋值 高亮红框
            if GamePlayGuideMgr.rectTarget then
                cs_coroutine.stop(self.coShowImgHighLight)
                self.coShowImgHighLight = nil
                self.Layer_Mask:StopCoroutine()
                local aimValue = GamePlayGuideMgr.rectTarget
                self:SetHighLightShow(aimValue, true)
                self:SetValueHighLight(aimValue)
            end
        else
            KTool.SetActive(self.Btn_ToNext.gameObject, false)
            GamePlayGuideMgr.booleanIsYield = false
        end
    end
    self.eventOnOrientationChange = Events.AddListener("CHANGE_DEVICE_ORIENTATION", Bind(self, self.ResetShaderOnOrientationChange))
end

function UIGamePlayGuideDialog:RemoveListener()
    Events.RemoveListener("CHANGE_DEVICE_ORIENTATION", self.eventOnOrientationChange)
end
------------ Event

function UIGamePlayGuideDialog:ResetShaderOnOrientationChange()
    -- print("ResetShaderOnOrientationChange --------->>>>")
    if self.typeShowState == TYPE_SHADER.Single and self.target then
        self.Layer_Mask:FocusOn(self.target, true)
        self.Img_HighLight.transform.position = self.target.transform.position
    elseif self.typeShowState == TYPE_SHADER.Plural and self.listGOHighLightPlural then
        local list = {}
        for i, rect in ipairs(self.listRectImgHighLight) do
            table.insert(list, rect)
        end
        for i = #list, 4, 1 do
            local lastItem = list[#list]
            table.insert(list, lastItem)
        end
        self.Layer_Mask:FocusOnPlural(list)
        for i, goImg in ipairs(self.listRectImgHighLight) do
            goImg.transform.position = self.listGOHighLightPlural[i].transform.position
        end
    end
end

