---SetPosImgHighLight
---设置 高亮框 的大小和位置
---@param gameObject UnityEngine.GameObject
function UIGamePlayGuideDialog:SetPosImgHighLight(gameObject)
    if IsNull(gameObject) then return end
    self.Img_HighLight.transform.position = gameObject.transform.position  -- 位置
    local goRect = gameObject:GetComponent(typeof(RectTransform))
    local goSize = goRect.rect
    local scale = goRect.transform.localScale
    local rotation = goRect.transform.rotation
    self.V2Img_HighLight = Vector2.New((goSize.width * scale.x + OFFSET_IMG_HIGH_LIGHT_WIDTH) , (goSize.height * scale.y + OFFSET_IMG_HIGH_LIGHT_HIGHT))
    self.Img_HighLight.sizeDelta = self.V2Img_HighLight
    self.Img_HighLight.transform.rotation = rotation
    self:SetDescPosition()
    self:PlayHighLightAnimation()
    --self.coShowImgHighLight = self:ShowImgHighLight()
end

---SetImgHighLightWithData
---@param Size Vector2
---@param pos Vector2
function UIGamePlayGuideDialog:SetImgHighLightWithData(Size, pos)
    if GamePlayGuideMgr.ifFrame <= 0 then return end
    self.Img_HighLight.transform.position = pos
    local finalV2 = Vector2.New(Size.x + OFFSET_IMG_HIGH_LIGHT_WIDTH, Size.y + OFFSET_IMG_HIGH_LIGHT_HIGHT)
    self.V2Img_HighLight = finalV2
    self.Img_HighLight.sizeDelta = self.V2Img_HighLight
    self.Img_HighLight.transform.rotation = Quaternion.Euler(0, 0, 0)
    self:SetDescPosition()
    self:PlayHighLightAnimation()
    --self.coShowImgHighLight = self:ShowImgHighLight()
end

function UIGamePlayGuideDialog:SetDescPosition()
    if GamePlayGuideMgr.descShowType == GamePlayGuideMgr.DESC_SHOW_TYPE.POS_CONFIG then return end
    local descData = GamePlayGuideMgr.dataDesc
    if isNull(descData) then return end
    local desc = descData.desc
    local role = descData.role
    local title = descData.descTitle
    local anchorPos = self.Img_HighLight
    local size =  self.V2Img_HighLight
    local isShowRole = not (role == "0" or role == "" or IsNull(role))
    self.tableDescWithCharacter:ShowDescWithScreenData(desc, isShowRole, title, anchorPos, size, role)
    self.tableDescWithCharacter:SetRootShowState(true)
end

---SetValueHighLight
---设置 高亮红框
---@param Size Vector2 游戏物体大小
---@param pos Vector3 游戏物体位置
function UIGamePlayGuideDialog:SetValueHighLight(goRect)
    local size = Vector2.New(goRect.sizeDelta.x + OFFSET_IMG_HIGH_LIGHT_WIDTH, goRect.sizeDelta.y + OFFSET_IMG_HIGH_LIGHT_HIGHT)
    local pos = goRect.position
    self.Img_HighLight.sizeDelta = size -- 大小
    self.Img_HighLight.transform.position = pos -- 位置
    self.Img_HighLight.transform.rotation = Quaternion.Euler(0, 0, 0)
end

---ShowImgHighLight
---高亮红框 动效
---@return UnityEngine.Coroutine
function UIGamePlayGuideDialog:ShowImgHighLight()
    if self.goImgHighLight then
        KTool.SetActive(self.goImgHighLight, true)
    end
    local coShow
    self.Img_HighLight.sizeDelta = Vector2.zero
    local startTime = os.clock()
    if self.Img_HighLight then
        coShow = cs_coroutine.start(function()
            self:AddCo2List(coShow)
            local curLength = 0
            while curLength <= HIGH_LIGHT_IMG_LENGTH do
                local curProcess = curLength / HIGH_LIGHT_IMG_LENGTH
                curProcess = curProcess > 1 and 1 or curProcess
                self.Img_HighLight.sizeDelta = Vector2.New(self.V2Img_HighLight.x * curProcess,
                        self.V2Img_HighLight.y * curProcess)
                curLength = os.clock() - startTime
                cs_coroutine.yield_return()
            end
            self.Img_HighLight.sizeDelta = self.V2Img_HighLight
            coShow = nil
        end)
    end
    return coShow
end

---SetImgHighLightPlural
---设置多高亮区域展示 Img
---@param listArea table 需要高亮区域的 GO 集合
function UIGamePlayGuideDialog:SetImgHighLightPlural(listArea)
    if GamePlayGuideMgr.ifFrame <= 0 then return end
    if IsNull(self.goImgHighLight) then return end
    if IsNull(listArea) or #listArea <= 0 then return end
    self.listGOHighLightPlural = listArea --- 需要高亮区域的游戏物体集合
    local goSample = self.goImgHighLight
    local numAreas = #self.listGOHighLightPlural
    if IsNull(self.listRectImgHighLight) then
        self.listRectImgHighLight = {}
    end
    for i = 1, numAreas do
        local goImg = GameObject.Instantiate(goSample, self.Layer_ShowElement.transform)
        goImg.transform.position = self.listGOHighLightPlural[i].transform.position
        local rectHighLight = self.listGOHighLightPlural[i]:GetComponent(typeof(RectTransform))
        local rectImg = KTool.GetOrAddComponent(goImg, typeof(RectTransform))
        rectImg.sizeDelta = rectHighLight.sizeDelta
        table.insert(self.listRectImgHighLight, rectImg)
    end
end

