---SetHighLightPlural
---多区域高亮
---@param listRect table 位置集合
function UIGamePlayGuideDialog:SetHighLightPlural(listGO)
    if self.Layer_Mask then
        KTool.SetActive(self.goRootLayer_Mask, true)
        -- print("UIGamePlayGuideDialog:SetHighLightPlural ------->>>>")
        local list = {}
        for i = 1, #listGO do
            local go = listGO[i].gameObject
            local rectTransform = KTool.GetComponent(go, typeof(RectTransform))
            table.insert(list, rectTransform)
        end
        for i = #listGO + 1, 4, 1 do
            local lastItem = list[#list]
            table.insert(list, lastItem)
        end
        xTry(function() 
                self.Layer_Mask:FocusOnPlural(list)
            self.typeShowState = TYPE_SHADER.Plural
        end)
    end
end

