function UIGamePlayGuideDialog:SetHighLightShow(target, isImmediately)
    isImmediately = true
    if self.Layer_Mask then
        KTool.SetActive(self.goRootLayer_Mask, true)
        local Immediately
        if IsNull(isImmediately) then
            Immediately = false
        else
            Immediately = isImmediately
        end
        -- print("UIGamePlayGuideDialog:SetHighLightShow ------->>>>")
        self.target = target
        self.Layer_Mask:FocusOn(target, Immediately)
        self.typeShowState = TYPE_SHADER.Single
    end
end

