function UIGamePlayGuideDialog:SetDialogLayer(numLayer)
    local orderTracker = self.controller.gameObject:GetComponent(typeof(CS.Engine.UI.OrderTracker))
    if orderTracker then
        print(orderTracker)
        orderTracker.addSortingOrder = numLayer
    end
    local Canvas = CS.UnityEngine.Canvas
    local canvasShowLayer = self.Layer_ShowElement.gameObject:GetComponent(typeof(Canvas))
    local canvasInteractable = self.Layer_Interactable.gameObject:GetComponent(typeof(Canvas))
    if canvasShowLayer then
        canvasShowLayer.overrideSorting = true
        canvasShowLayer.sortingOrder = numLayer + 20
    end
    if canvasInteractable then
        canvasInteractable.overrideSorting = true
        canvasInteractable.sortingOrder = numLayer + 30
    end
end

