function UIGamePlayGuideDialog:InitGuideRole()
    if not isNull(self.guideCameraGo) then return self.guideCameraGo end
    self.guideCameraGo = GuideUtils.InitGuideRole(function(go) 
        local goGuider = go
        if not IsNull(goGuider) then
            self.animatorGuider = KTool.GetComponent(goGuider, typeof(Animator))
        end
    end)
    local captureCamera = self.guideCameraGo.gameObject:GetComponentInChildren(typeof(CS.UnityEngine.Camera))
    local rawImage = self.tableDescWithCharacter.Img_WithRole
    rawImage.texture = captureCamera.targetTexture
end

function UIGamePlayGuideDialog:PlayAnimationGuider(strTrigger)
    if not IsNull(self.animatorGuider) then
        self.animatorGuider:SetTrigger(checkString(strTrigger))
    end
end


return UIGamePlayGuideDialog
